function validatePoint(x, y, r) {
	let valid = true;
	var rr = r;
	for(let k=0; k<circles.length; k++) {
		if(dist(x, y, circles[k].x, circles[k].y)>=(rr+circles[k].r)) continue;
		else rr = dist(x, y, circles[k].x, circles[k].y)-circles[k].r;
	}
	return rr;
}

