function createPath(points, radiusAll) {
  let polyPath = new Path2D();

  let radius = radiusAll;
  let len = points.length;
  let p1 = points[len-1];
  let arcPath = [];

  for(let i=0; i<len; i++) {
    let p2 = points[i%len];
    let p3 = points[(i+1)%len];

    let A = createVector(p1.x, p1.y);
    let B = createVector(p2.x, p2.y);
    let C = createVector(p3.x, p3.y);

    let BA = A.sub(B), BC = C.sub(B);
    let BAnorm = BA.copy().normalize(), BCnorm = BC.copy().normalize();

    let sinA = -BAnorm.dot(BCnorm.copy().rotate(HALF_PI));
    let sinA90 = BAnorm.dot(BCnorm);
    let angle = asin(sinA);

    let radDirection =1, drawDirection = false;
    if(sinA90 <0) {
      angle<0 ? (angle +=PI) : ((angle+=PI), radDirection = -1, drawDirection = true);
    } else {
      angle>0 ? ((radDirection = -1), (drawDirection = true)):0;
    }

		// if(radiusAll>dist(p1.x, p1.y, p3.x, p3.y)/5) radius = dist(p1.x, p1.y, p3.x, p3.y)/5;
		// else radius = radiusAll;
    p2.radius ? (radius = p2.radius) : (radius = radiusAll);
    let halfAngle = angle/2;
    let lenOut = abs((cos(halfAngle)*radius)/sin(halfAngle));

    let cRadius;
    if(lenOut > min(BA.mag()/2, BC.mag()/2)) {
      lenOut > min(BA.mag()/2, BC.mag()/2);
      cRadius = abs(lenOut*sin(halfAngle)/cos(halfAngle));
    } else {
      cRadius = radius;
    }

    let x = B.x+BC.normalize().x*lenOut - BC.normalize().y*cRadius*radDirection;
    let y = B.y+BC.normalize().y*lenOut + BC.normalize().x*cRadius*radDirection;


    //draw codes
    polyPath.arc(x, y, cRadius, BA.heading() + PI/2*radDirection, BC.heading()-PI/2*radDirection, drawDirection);

    p1 = p2;
    p2 = p3;
  }
	return polyPath;
}

function pixelShift(canvas, n) {
  // console.log("applying pixel shift!");
  canvas.loadPixels();
  for(let i=0; i<canvas.width; i++) {
    for(let j=0; j<canvas.height; j++) {
      let idx = (j*canvas.width+i)*4;
      // let jiggle = random(-n, n);
      canvas.pixels[idx]+=random(-n, n);
      canvas.pixels[idx+1]+=random(-n, n);
      canvas.pixels[idx+2]+=random(-n, n);
    }
  }
  canvas.updatePixels();
}


