function createPoly(cx, cy, rmin, rmax, canvas) {
	canvas.push();
	var path = [];
	var a = 0;
	for(let i=0; i<7; i++) {
		path.push({x:cx+random(canvas.width/3, canvas.width/2)*cos(a), y:cy+random(canvas.width/3, canvas.width/2)*sin(a)});
