		} else {
			break;
		}
	}

	let c = color(random(palette));
	c.setAlpha(60);
	canvas.drawingContext.fillStyle = c;
	let blurr = map(dist(cx, cy, canvas.width/2, canvas.height/2), 0, max(canvas.width/2, canvas.height/2)*1.5, canvas.width/60, canvas.width/30);
